//! TF_DS_IDX_PICK_WIDE (off by default): the indexer's small-row selection past idx_fused's 16,384-block staging
//! bound, up to 65,536 blocks (long-context decode). The small-row form's first launch (tf_ds_block_max_kernel) is
//! unchanged; the selection's second launch becomes tf_ds_idx_pick_wide_kernel: the same tf_ds_idx_select reading the
//! row's block maxima from global memory (L2-resident: one fp32 maximum a block, <= 256 KiB a row at 65,536 blocks)
//! instead of staging all of them on chip, so the shared-memory bound no longer applies. The bound is the radix
//! shortcut's, not the staging's: tf_ds_pool_cut fixes the inverted column's two high bytes at 0xffff, which holds to
//! 65,536 blocks (a column's inverted id leaves 0xFFFE in them at 65,537, where the unfused fallback stays). The
//! block list (cblk) and its `every` masking are byte-identical to the unfused sequence's: the same total order on
//! (score bits, inverted column), ties to the lower column (idx_fused's host reference describes the same selection).
//! Decode only (the block list): the prompt arm's mask keeps its arms. A malformed switch refuses startup. The
//! launcher is Ops.idxPickWide and the call site is round.zig's candidate-source arm.
const std = @import("std");
const idx_fused = @import("idx_fused.zig");

pub const env_name: [:0]const u8 = "TF_DS_IDX_PICK_WIDE";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadIdxPickWide}!bool {
    return parse(text) orelse error.BadIdxPickWide;
}

/// The selection's block-count bound: the radix shortcut's, 65,536 blocks (524,288 columns at the served block size,
/// the 1,048,576-token bucket at ratio 2). 65,537 must keep the unfused fallback (todo.md, "Extend 0195 to 100K+").
pub const max_nbk = 65536;

/// Whether the wide selection supports this configuration: decode only (the block list; the prompt arm writes the
/// mask), the small-row form's row bound (one CTA a row), and the pool's regime past the on-chip staging bound up to
/// `max_nbk`. The call sites fall back to the unfused sequence when it does not.
pub fn wideOk(wide: bool, allow_small: bool, rows: usize, width: usize, bsize: usize, nbk: usize, k: usize) bool {
    return wide and allow_small and rows >= 1 and rows <= idx_fused.small_rows and
        width >= 1 and width <= std.math.maxInt(c_int) and bsize >= 1 and bsize <= std.math.maxInt(c_int) and
        nbk == 1 + (width - 1) / bsize and nbk > idx_fused.max_nbk and nbk <= max_nbk and
        k >= 1 and k <= idx_fused.max_k and k <= nbk;
}

const expectEqual = std.testing.expectEqual;

test "the switch parses its forms and nothing else" {
    try expectEqual(false, parse(null).?);
    try expectEqual(false, parse("").?);
    try expectEqual(false, parse("0").?);
    try expectEqual(true, parse("1").?);
    try expectEqual(@as(?bool, null), parse("2"));
    try expectEqual(@as(?bool, null), parse("yes"));
    try expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadIdxPickWide, fromText("2"));
}

test "wideOk takes the wide window and nothing else" {
    const w16385: usize = 8 * 16385 - 3; // the smallest wide column count (nbk 16,385, a short last block)
    try std.testing.expect(wideOk(true, true, 7, w16385, 8, 16385, 2048)); // the bound's first step, rows at the cap
    try std.testing.expect(wideOk(true, true, 1, 8 * 32768, 8, 32768, 2048)); // the 524,288-token bucket at ratio 2
    try std.testing.expect(wideOk(true, true, 7, 8 * 65536, 8, 65536, 2048)); // the max_nbk cap, inclusive
    try std.testing.expect(wideOk(true, true, 7, 8 * 65536, 8, 65536, 1)); // k 1 is fine (k <= max_k)
    try std.testing.expect(!wideOk(true, true, 7, 8 * 65537, 8, 65537, 2048)); // 65,537: the unfused fallback stays
    try std.testing.expect(!wideOk(true, true, 7, 8 * 16384, 8, 16384, 2048)); // the staging bound is idx_small's
    try std.testing.expect(!wideOk(true, true, 8, w16385, 8, 16385, 2048)); // past the small-row bound
    try std.testing.expect(!wideOk(true, false, 7, w16385, 8, 16385, 2048)); // prompt keeps its arms (no block list)
    try std.testing.expect(!wideOk(false, true, 7, w16385, 8, 16385, 2048)); // the switch off
    try std.testing.expect(!wideOk(true, true, 0, w16385, 8, 16385, 2048));
    try std.testing.expect(!wideOk(true, true, 7, w16385, 8, 16386, 2048)); // nbk disagrees with width/bsize
    try std.testing.expect(!wideOk(true, true, 7, w16385, 8, 16385, 2049)); // k past the 2048 cap
    try std.testing.expect(!wideOk(true, true, 7, w16385, 8, 16385, 0));
    try std.testing.expect(!wideOk(true, true, 7, 0, 8, 0, 0)); // an empty width
}

test "the radix shortcut's constant column bytes hold to 65,536 blocks and not at 65,537" {
    // tf_ds_pool_cut's prefix 0xffff0000 fixes the key's inverted-column high bytes; that is the bound max_nbk
    // states, checked on the key's own bytes
    const hi = struct {
        fn of(j: usize) u32 {
            return @truncate((idx_fused.scoreKey(0, j) & 0xFFFFFFFF) >> 16);
        }
    };
    try expectEqual(@as(u32, 0xFFFF), hi.of(0));
    try expectEqual(@as(u32, 0xFFFF), hi.of(max_nbk - 1)); // 65,535: the last column the shortcut covers
    try expectEqual(@as(u32, 0xFFFE), hi.of(max_nbk)); // 65,536: the prefix no longer matches its keys
}

