// One CTA owns a candidate row. Keep the maxima on chip for radix selection.
// Compact selected columns in input order so neither the mask nor the list needs a sort. The maxima and the selection
// live only on chip: the call sites read the mask (the prompt arm) or the block list (decode), never bmax/pidx, so the
// fused launch writes neither (the unfused blockMax/topkIndices/poolPick sequence still does).
// The block maxima (tf_ds_block_max_kernel's rule) for every block this thread owns, on chip. BS == 8 is the served
// block size, instantiated with the trip count static: two aligned 16-byte loads a block, then the same comparison order
// as the scalar loop (a NaN wins; otherwise a greater score replaces the maximum), and a guarded scalar tail for the
// row's last partial block. BS == 0 keeps the runtime size (every other `bsize` and every unfused-shape fallback).
template <int BS>
__device__ __forceinline__ void tf_ds_block_max_t(float* maxima, const float* row, int width, int nb, long long last,
                                                  int bsize = 0) {
    const float ninf = -__int_as_float(0x7f800000);
    const int bs = BS ? BS : bsize;
    for (int b = threadIdx.x; b < nb; b += blockDim.x) {
        const float* s = row + (long long)b * bs;
        float m = ninf;
        bool nan = false;
        if (BS == 8 && b * 8 + 8 <= width) {
            const float4 lo = *reinterpret_cast<const float4*>(s);
            const float4 hi = *reinterpret_cast<const float4*>(s + 4);
            const float x[8] = {lo.x, lo.y, lo.z, lo.w, hi.x, hi.y, hi.z, hi.w};
            #pragma unroll
            for (int j = 0; j < 8; ++j) {
                if (x[j] != x[j]) nan = true;
                else if (x[j] > m) m = x[j];
            }
        } else {
            for (int j = 0; j < bs && b * bs + j < width; ++j) {
                const float x = s[j];
                if (x != x) nan = true;
                else if (x > m) m = x;
            }
        }
        float v = nan ? __int_as_float(0x7fc00000) : m;
        if (b == last) v = __int_as_float(0x7f800000);
        maxima[b] = v;
    }
}

// The pool's selection and its two outputs: the cutoff on the score digits with the tied columns resolved during
// compaction (tf_ds_pool_cut), then either the mask alone (the prompt arm: no ballot, prefix sum or compaction) or the
// decode arm's ascending block list. `maxima` is one block a column - on chip for the fused/pick forms, the global
// maxima row for the wide pick (read only here either way), `limit` the row's `every`.
__device__ __forceinline__ void tf_ds_idx_select(const float* maxima, int nb, int k, uint8_t* mask, long long ms,
                                                 int* cblk, int r, long long limit) {
    __shared__ unsigned long long prefix_s, mask_s;
    __shared__ int want_s;
    __shared__ int warp_end[32];
    if (threadIdx.x == 0) {
        // k == nb picks every block: mask 0 makes every key "tied", and want 0 picks the whole bin
        const bool all = k == nb;
        prefix_s = all ? 0ull : 0xffff0000ull;   // (inverted columns below 8192 have two constant high bytes)
        mask_s = all ? 0ull : 0xffff0000ull;
        want_s = all ? 0 : k;
    }
    __syncthreads();
    if (k != nb) tf_ds_pool_cut(maxima, nb, &prefix_s, &mask_s, &want_s);
    __syncthreads();
    const unsigned long long prefix = prefix_s, cmask = mask_s;
    const int want = want_s;
    const float ninf = -__int_as_float(0x7f800000);
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (cblk == nullptr) {
        // the prompt arm reads only the mask: each block's bit straight from the cutoff, no ballot, prefix sum or
        // compaction unless the cutoff straddles ties (then the tied columns' order needs the prefix)
        int tied_base = 0;
        for (int first = 0; first < nb; first += blockDim.x) {
            const int col = first + threadIdx.x;
            const bool in = col < nb;
            const float value = in ? maxima[col] : ninf;
            const unsigned long long u = tf_ds_score_key(value, col);
            bool picked;
            if (want == 0) picked = in && (u >= prefix);   // (the whole cutoff bin, no tie split)
            else {
                const bool above = in && ((u & cmask) > prefix);
                const bool tied = in && ((u & cmask) == prefix);
                int before, total;
                before = tf_ds_tile_prefix(tied, warp_end, &total, lane, warp);
                picked = above || (tied && (tied_base + before) < want);
                tied_base += total;
                __syncthreads();   // the tile's total is read before warp_end is reused
            }
            if (mask != nullptr && in) mask[(long long)r * ms + col] = (uint8_t)(picked && col < limit && value > ninf);
        }
    } else {
        // decode: compact the selected blocks in ascending column order (the tied cutoff's slots go to its lowest
        // columns, which is the ascending scan's first `want` of them)
        int base = 0, tied_base = 0, ttotal = 0;
        for (int first = 0; first < nb; first += blockDim.x) {
            const int col = first + threadIdx.x;
            const bool in = col < nb;
            const float value = in ? maxima[col] : ninf;
            const unsigned long long u = tf_ds_score_key(value, col);
            bool picked;
            if (want == 0) picked = in && (u >= prefix);   // (the whole cutoff bin, no tie split)
            else {
                const bool above = in && ((u & cmask) > prefix);
                const bool tied = in && ((u & cmask) == prefix);
                const int tbefore = tf_ds_tile_prefix(tied, warp_end, &ttotal, lane, warp);
                picked = above || (tied && (tied_base + tbefore) < want);
                tied_base += ttotal;
                __syncthreads();   // the tied total is read before warp_end is reused
            }
            int before, total;
            before = tf_ds_tile_prefix(picked, warp_end, &total, lane, warp);
            const bool valid = picked && col < limit && value > ninf;
            if (mask != nullptr && in) mask[(long long)r * ms + col] = (uint8_t)valid;
            if (picked) cblk[(long long)r * k + base + before] = valid ? col : -1;
            base += total;
            __syncthreads();   // all warps consumed the offsets before the next tile
        }
    }
}

extern "C" __global__ void __launch_bounds__(1024) tf_ds_idx_fused_kernel(const float* score, long long ss, int width,
                                                                          int bsize, const long long* vis,
                                                                          const long long* every, int k,
                                                                          uint8_t* mask, long long ms, int* cblk,
                                                                          int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.x;
    const int nb = 1 + (width - 1) / bsize;
    extern __shared__ float maxima[];
    const float* row = score + (long long)r * ss;
    // phase 1: the block maxima; the served block size with a 16-byte-aligned row stride takes the static, vectorized
    // form, anything else the runtime loop (the same arithmetic, so both are byte-identical)
    const long long visible = vis[r];
    const long long last = visible > 0 ? (visible - 1) / bsize : -1;
    if (bsize == 8 && (ss & 3) == 0) tf_ds_block_max_t<8>(maxima, row, width, nb, last);
    else tf_ds_block_max_t<0>(maxima, row, width, nb, last, bsize);
    __syncthreads();
    tf_ds_idx_select(maxima, nb, k, mask, ms, cblk, r, every[r]);
}

